"use client";

import { useState } from "react";
import SubsystemCard from "./SubsystemCard";
import SubsystemModal, {
  SubsystemFormData,
} from "./SubsystemModal";

interface Subsystem {
  id: string;
  name: string;
  category: string;
  description: string;
  elements: string[];
  status: "Defined" | "Needs Work";
}

const initialSubsystems: Subsystem[] = [
  {
    id: "1",
    name: "Power System",
    category: "Electrical",
    description:
      "Provides, distributes, and manages electrical power throughout the system.",
    elements: [
      "Battery",
      "BMS",
      "Power Distribution",
    ],
    status: "Defined",
  },
  {
    id: "2",
    name: "Computing",
    category: "Computing",
    description:
      "Provides onboard computation, AI processing, and data storage.",
    elements: [
      "Main Computer",
      "AI Accelerator",
      "Storage",
    ],
    status: "Defined",
  },
  {
    id: "3",
    name: "Sensors",
    category: "Sensors",
    description:
      "Collects environmental and system-state information.",
    elements: [
      "Cameras",
      "IMU",
      "LiDAR",
    ],
    status: "Needs Work",
  },
];

export default function Architecture() {
  const [subsystems, setSubsystems] =
    useState<Subsystem[]>(initialSubsystems);

  const [modalOpen, setModalOpen] = useState(false);

  const [editingSubsystem, setEditingSubsystem] =
    useState<Subsystem | undefined>();

  function openAddModal() {
    setEditingSubsystem(undefined);
    setModalOpen(true);
  }

  function openEditModal(subsystem: Subsystem) {
    setEditingSubsystem(subsystem);
    setModalOpen(true);
  }

  function closeModal() {
    setModalOpen(false);
    setEditingSubsystem(undefined);
  }

  function handleSubmit(data: SubsystemFormData) {
    if (editingSubsystem) {
      setSubsystems((current) =>
        current.map((subsystem) =>
          subsystem.id === editingSubsystem.id
            ? {
                ...subsystem,
                ...data,
              }
            : subsystem
        )
      );
    } else {
      setSubsystems((current) => [
        ...current,
        {
          id: crypto.randomUUID(),
          ...data,
        },
      ]);
    }

    closeModal();
  }

  function deleteSubsystem(id: string) {
    setSubsystems((current) =>
      current.filter(
        (subsystem) => subsystem.id !== id
      )
    );
  }

  return (
    <div className="h-full overflow-y-auto">
      <div className="mx-auto max-w-5xl p-8">
        <div className="flex items-start justify-between gap-6">
          <div>
            <h2 className="text-2xl font-semibold">
              Architecture
            </h2>

            <p className="mt-2 text-sm text-white/40">
              Define the major subsystems that make up your
              system.
            </p>
          </div>

          <button
            onClick={openAddModal}
            className="shrink-0 rounded-lg bg-white px-4 py-2 text-sm font-medium text-black transition hover:bg-white/90"
          >
            + Add Subsystem
          </button>
        </div>

        <div className="mt-8 grid gap-4 md:grid-cols-2">
          {subsystems.map((subsystem) => (
            <SubsystemCard
              key={subsystem.id}
              subsystem={subsystem}
              onEdit={openEditModal}
              onDelete={deleteSubsystem}
            />
          ))}
        </div>

        {subsystems.length === 0 && (
          <div className="mt-8 rounded-xl border border-dashed border-white/10 p-12 text-center">
            <p className="text-sm text-white/40">
              No subsystems yet.
            </p>

            <button
              onClick={openAddModal}
              className="mt-4 rounded-lg bg-white px-4 py-2 text-sm font-medium text-black"
            >
              Add Subsystem
            </button>
          </div>
        )}
      </div>

      <SubsystemModal
        open={modalOpen}
        subsystem={editingSubsystem}
        onClose={closeModal}
        onSubmit={handleSubmit}
      />
    </div>
  );
}